from .pricing import quote
from .receipts import Receipt

class Checkout:
    def __init__(self, inventory, ledger):
        self.inventory = inventory
        self.ledger = ledger
        self.receipts = {}

    def place_order(self, request_id, lines, member=False):
        if request_id in self.receipts:
            return self.receipts[request_id]
        if not lines:
            raise ValueError("empty order")
        amount = quote(lines, member)["total_cents"]
        needed = {}
        for sku, qty in lines:
            needed[sku] = needed.get(sku, 0) + qty
        for sku, qty in needed.items():
            if self.inventory.stock.get(sku, 0) < qty:
                raise ValueError("insufficient stock")
        self.inventory.reserve(lines)
        try:
            paid = self.ledger.charge(request_id, amount)
        except BaseException:
            self.inventory.release(lines)
            raise
        receipt = Receipt(request_id, paid)
        self.receipts[request_id] = receipt
        return receipt
EOF
